<script lang="ts">
 import { requests } from '$lib/stores/requests';
 import { requestBackendAvailable } from '$lib/wasm';
 import { MAX_REQUEST_TEXT_UTF8_BYTES, type RequestDraft } from '$lib/request-types';
 let { draft, onOpenConversation }: { draft: RequestDraft; onOpenConversation:(id:string,requiresAcceptance:boolean)=>void }=$props();
 let length=$derived(new TextEncoder().encode(draft.input.text).length);
 let outcome=$derived(draft.outcome);
 let editable=$derived(draft.phase==='draft');
</script>
<section class="request-compose" aria-label="New message request">
 <button class="back" onclick={()=>requests.showInbox()}>← Message requests</button>
 <header><p class="eyebrow">AN ENCRYPTED INTRODUCTION</p><h1>Say hello to {draft.recipientLabel}</h1><p>Your first message arrives in Requests. You can keep chatting once they accept.</p></header>
 {#if !requestBackendAvailable}<p class="notice">Sending encrypted requests isn’t available in this browser yet. This draft stays on this screen.</p>{/if}
 {#if $requests.error}<p class="notice error" role="alert">{$requests.error}</p>{/if}
 <div class="letter"><label for="request-message">Your message</label><textarea id="request-message" value={draft.input.text} oninput={e=>requests.saveText(draft.input.draftId,e.currentTarget.value)} disabled={!editable || $requests.busy} placeholder="What would you like to say?" rows="8" aria-describedby="request-scope"></textarea><footer><span id="request-scope">Text only · end-to-end encrypted</span><span class:over={length>MAX_REQUEST_TEXT_UTF8_BYTES}>{length} / {MAX_REQUEST_TEXT_UTF8_BYTES.toLocaleString()} bytes</span></footer></div>
 {#if draft.input.invitation}<p class="notice">This message includes a group invitation. Sending the note does not accept or join the group.</p>{/if}
 {#if outcome?.type==='requestSent'}<div class="result" role="status"><h2>Request sent</h2><p>Your introduction is saved. Further messages wait for acceptance.</p><button onclick={()=>onOpenConversation(outcome?.type==='requestSent'?outcome.conversationId:'',false)}>View request</button></div>
 {:else if outcome?.type==='existingDirect'}<div class="result" role="status"><h2>A conversation already exists</h2><p>{draft.noteDelivery?.messageId?'Your invitation note is saved in the existing conversation.':draft.noteDelivery?'Check the existing conversation for this note.':outcome.requiresAcceptance?'Review the incoming request before replying. Your unsent introduction is still here.':'Your introduction has not been sent to the existing conversation.'}</p><button onclick={()=>onOpenConversation(outcome?.type==='existingDirect'?outcome.conversationId:'',outcome?.type==='existingDirect'&&outcome.requiresAcceptance)}>Open conversation</button>{#if draft.input.invitation && !outcome.requiresAcceptance}{#if draft.noteDelivery}<p>{draft.noteDelivery.messageId?'Invitation note sent. The group invitation remains separate.':'Invitation note delivery is not confirmed. Open the conversation to check before composing another note.'}</p>{:else}<button class="primary" disabled={$requests.busy || !requestBackendAvailable} onclick={()=>requests.sendInvitationNote(draft.input.draftId)}>Send invitation note</button><p>This sends your saved note as a separate encrypted message in the existing chat.</p>{/if}{/if}</div>
 {:else if outcome?.type==='terminalNotPublished'}<div class="result" role="status"><h2>Request wasn’t sent</h2><p>Your text is retained. You can start an editable draft when you’re ready.</p><button onclick={()=>requests.begin(draft.input.recipientDid,draft.recipientLabel,draft.input.text,draft.input.invitation??undefined)}>Edit a new draft</button></div>
 {:else}<div class="actions"><button disabled={$requests.busy} onclick={()=>requests.cancel(draft.input.draftId)}>{editable?'Cancel draft':'Cancel request attempt'}</button><div>{#if !editable}<button disabled={$requests.busy || !requestBackendAvailable} onclick={()=>requests.resume(draft.input.draftId)}>Check delivery</button>{/if}<button class="primary" disabled={$requests.busy || !requestBackendAvailable || !draft.input.text.trim() || length>MAX_REQUEST_TEXT_UTF8_BYTES} onclick={()=>requests.send(draft.input.draftId)}>{$requests.busy?'Checking…':editable?'Send introduction':'Retry same request'}</button></div></div>{/if}
 {#if !editable && outcome?.type!=='requestSent' && outcome?.type!=='terminalNotPublished' && outcome?.type!=='existingDirect'}<p class="muted" role="status">Delivery is not confirmed. Checking or retrying keeps the same request identity.</p>{:else if editable}<p class="muted">Nothing is sent until you choose Send introduction.</p>{/if}
</section>
<style>
.request-compose{max-width:790px;width:100%;margin:auto;padding:36px;overflow:auto}.back{border:0;background:none;padding:0;color:var(--text-secondary);margin-bottom:36px}h1{font-size:29px;letter-spacing:-.035em;margin:10px 0 14px}header>p:not(.eyebrow),.muted,.result p{color:var(--text-secondary);line-height:1.6;font-size:14px}.eyebrow{font-size:10px;letter-spacing:.15em;font-weight:700;color:var(--accent)}.letter{margin-top:30px;border:1px solid var(--border);border-radius:16px;background:var(--bg-secondary);padding:20px}label{display:block;font-size:12px;color:var(--text-secondary);margin-bottom:14px}textarea{width:100%;resize:vertical;min-height:180px;border:0;outline:none;background:transparent;color:var(--text-primary);font:inherit;line-height:1.7}textarea:disabled{opacity:.8}.letter footer{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--border);padding-top:15px;color:var(--text-tertiary);font-size:11px}.actions{display:flex;justify-content:space-between;gap:10px;margin-top:22px}.actions>div{display:flex;gap:10px}button{font:inherit;border:1px solid var(--border);border-radius:9px;background:var(--bg-card);color:var(--text-primary);padding:11px 17px;cursor:pointer;font-size:13px}button.primary{background:var(--accent);color:#fff;border-color:transparent}button:disabled{opacity:.45;cursor:default}.muted{font-size:12px;margin-top:20px}.notice,.result{border:1px solid var(--border);padding:18px;border-radius:12px;margin:20px 0;line-height:1.5;color:var(--text-secondary)}.error,.over{color:#e7958d}.result h2{color:var(--text-primary);font-size:18px}@media(max-width:600px){.request-compose{padding:24px 18px}h1{font-size:24px}.actions,.actions>div{flex-wrap:wrap}}
</style>
